def texte(code):
    """Alle Texte einer Sprache. Fehlt ein Schlüssel, kommt der deutsche Text."""
    grund = TEXTE[GRUNDSPRACHE]
    if code == GRUNDSPRACHE or code not in TEXTE:
        zusammen = dict(grund)
    else:
        zusammen = dict(grund)
        zusammen.update({k: v for k, v in TEXTE[code].items() if v})
    # Die Anschrift ist in jeder Sprache dieselbe und steht nur oben in
    # ANBIETER. Der Eintrag in den Sprachblöcken dient nur dazu, dass
    # fehlende_texte() nichts vermisst.
    zusammen["set.anbieter"] = ANBIETER

    # Abschnitt 6 der Datenschutzerklärung hängt am Werbeschalter: mit
    # Werbung steht dort Google als Werbepartner, ohne Werbung steht dort,
    # dass die App keine Fremdanbieter einbindet. Der Platzhalter im Text
    # wird hier gefüllt, damit keine Stelle im Programm das nachhalten muss.
    # Dahinter kommt IMMER der Abo-Abschnitt: die Abrechnung spricht mit
    # Google Play, ob Werbung läuft oder nicht. Ohne diese Zeile stünde er
    # nirgends - der Baustein wäre da, aber unsichtbar.
    schluessel = "set.dsgvo_werbung_an" if WERBUNG_LAEUFT else "set.dsgvo_werbung_aus"
    zusammen["set.datenschutz_text"] = zusammen["set.datenschutz_text"].replace(
        "{werbung_abschnitt}",
        zusammen.get(schluessel, "") + "<br>" + zusammen.get("set.dsgvo_abo", ""))
    return zusammen


def anbieter_fehlt():
    """True, solange in ANBIETER noch die eckigen Klammern stehen."""
    return "[" in ANBIETER


def ustidnr_fehlt():
    """True, solange keine Umsatzsteuer-Identifikationsnummer im Impressum steht.

    § 5 Abs. 1 Nr. 6 DDG verlangt sie, SOBALD man eine hat – vorher nicht.
    Ajdin hat sie am 14.09.2026 im ELSTER-Fragebogen mitbeantragt (wegen
    AdMob, Reverse Charge an Google Irland). Das Finanzamt leitet den Antrag
    automatisch an das Bundeszentralamt für Steuern weiter, und das teilt die
    Nummer ausschließlich per Post mit – online ist nichts nachzusehen.

    Solange der Brief nicht da ist, fehlt im Impressum nichts. Deshalb steht
    in ANBIETER bewusst KEIN Platzhalter: der wäre in der App zu sehen und
    sähe nach Baustelle aus. Diese Prüfung erinnert nur den Entwickler.
    """
    return "USt-IdNr" not in ANBIETER


def fehlende_texte(code):
    """Schlüssel, die in dieser Sprache noch nicht übersetzt sind."""
    if code == GRUNDSPRACHE:
        return []
    vorhanden = TEXTE.get(code, {})
    return sorted(k for k in TEXTE[GRUNDSPRACHE] if not vorhanden.get(k))


def ist_sprache(code):
    return any(s["code"] == code for s in SPRACHEN)
